describe('yi: option-helper tuple slots', () => {
    const fx = (name: string, base: string, venue: string) => {
        const dir = path.join (rustFixtureRoot, name);
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), venue);
        return path.join (dir, 'ts/src/venue.ts');
    };
    const base = "export interface Dict { [key: string]: any }\nexport type Int = number | undefined;\nexport default class Exchange {\n    safeValue (o: any, k: any, d: any = undefined): any { return o[k]; }\\n    client (url: string): Client { return new Client (); }\n    checkOptionInteger (m: string, k: string, v: any): Int { return v; }\n    handleOptionIntegerAndParams (params: Dict, m: string, k: string, d: Int = undefined): [Int, Dict] {\n        const value = this.safeValue (params, k, d);\n        return [ this.checkOptionInteger (m, k, value), params ];\n    }\n    handleMaxEntriesPerRequestAndParams (method: string, maxEntriesPerRequest: Int = undefined, params: Dict = {}): [Int, any] {\n        const [ newMax, rest ] = this.handleOptionIntegerAndParams (params, method, 'maxEntriesPerRequest');\n        const option = (newMax !== undefined) ? newMax : maxEntriesPerRequest;\n        const resolved = (option === undefined) ? 1000 : option;\n        return [ resolved, rest ];\n    }\n    hold (x: any, y: any = undefined): any { return x; }\n}\n";
    test('yi: handleMaxEntriesPerRequestAndParams slot 0 (ternaries of exact ints over a defaulted Int parameter) is Option<i64>, boxed into this[name](..)', () => {
        const file = fx ('yi-max-entries', base, "import Exchange from './base/Exchange.js';\nimport type { Dict, Int } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async m (method: string, params: Dict = {}, maxEntriesPerRequest: Int = undefined) {\n        const [ perRequest, rest ] = this.handleMaxEntriesPerRequestAndParams (method, maxEntriesPerRequest, params);\n        return await this[method] (undefined, perRequest, rest);\n    }\n    n (method: string, params: Dict, other: any) {\n        const [ perRequest, rest ] = this.handleMaxEntriesPerRequestAndParams (method, undefined, params);\n        return this.hold (perRequest - other, rest);\n    }\n}\n");
        const out = transpiler.transpileRustByPath (file).content;
        expect(out).toContain('let mut perRequest: Option<i64> = ');
        expect(out).toContain('Value::from(perRequest)');
        // negative: an arithmetic operand against an any value keeps the box
        expect(out).toContain('let mut perRequest: Value = ');
    });
});

describe('ye: resolve proof for literal-map, cache-field and wildcard-hash resolves', () => {
    // one venue with a `watchT` awaiting 'ticker:' + symbol; `handlers` are the class's resolve sites
    const base = "export interface Dict { [key: string]: any }\nexport interface Dictionary<T> { [key: string]: T }\nexport interface Ticker { symbol: string; info: any }\nexport default class Exchange {\n    balance: Dict = {};\n    tickers: Dictionary<Ticker> = {};\n    other: any = {};\n    safeString (o: any, k: any, d: any = undefined): any { return o[k]; }\n    extend (...args: any[]): any { return Object.assign ({}, ...args); }\n    async watch (url: string, messageHash: string, message: any = undefined, subscribeHash: any = undefined, subscription: any = undefined): Promise<any> { return undefined; }\n    cleanUnsubscription (client: any, subHash: any, unsubHash: any) { client.resolve (true, unsubHash); }\n}\n";
    const mk = (handlers: string) => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-ye-'));
        fs.mkdirSync(path.join(root, 'ts/src/pro'), { recursive: true });
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/pro/venue.ts'), "import Exchange from '../base/Exchange.js';\nimport type { Dict, Ticker } from '../base/Exchange.js';\nexport default class venue extends Exchange {\n    async watchT (symbol: string) {\n        const ticker = await this.watch ('u', 'ticker:' + symbol);\n        const result: any = {};\n        result[this.safeString (ticker, 'symbol')] = ticker;\n        return result;\n    }\n" + handlers + "}\n");
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        return t.transpileRustByPath(path.join(root, 'ts/src/pro/venue.ts')).content;
    };
    const dictLocal = /let mut ticker: crate::value::Dict = self\.watch\(/;
    const valueLocal = /let mut ticker: Value = self\.watch\(/;
    const tk = "    handleTicker (client: any, message: Dict) {\n        const symbol: string = this.safeString (message, 's');\n";
    const cases: Array<[ string, string, RegExp ]> = [
        // (1) a map literal is a Dict resolve; negative: a list literal is not
        [ 'map literal', tk + "        client.resolve ({ 'symbol': symbol }, 'ticker:' + symbol);\n    }\n", dictLocal ],
        // ral-ze: a list literal is not a Dict resolve; it is now a proven List resolve
        [ 'negative: list literal', tk + "        client.resolve ([ symbol ], 'ticker:' + symbol);\n    }\n", /let mut ticker: crate::value::List = self\.watch\(/ ],
        // (2) `this.tickers[k]` right after `this.tickers[k] = <Ticker>`; negative: an `any` field
        [ 'cache field read after a typed write', tk + "        const parsed: Ticker = { 'symbol': symbol, 'info': message } as Ticker;\n        this.tickers[symbol] = parsed;\n        client.resolve (this.tickers[symbol], 'ticker:' + symbol);\n    }\n", dictLocal ],
        [ 'negative: any field read', tk + "        this.other[symbol] = message;\n        client.resolve (this.other[symbol], 'ticker:' + symbol);\n    }\n", valueLocal ],
        // (3) wildcard hashes: a `true` under a different literal prefix does not poison the proof; under a matching one it does
        [ 'bool under another prefix', tk + "        client.resolve ({ 'symbol': symbol }, 'ticker:' + symbol);\n    }\n    handleAuth (client: any, message: Dict) {\n        client.resolve (true, 'auth:' + this.safeString (message, 'id'));\n    }\n", dictLocal ],
        [ 'negative: bool under a matching prefix', tk + "        client.resolve ({ 'symbol': symbol }, 'ticker:' + symbol);\n    }\n    handleAuth (client: any, message: Dict) {\n        client.resolve (true, 'ticker:' + this.safeString (message, 'id'));\n    }\n", valueLocal ],
        // (4) cleanUnsubscription reads its hash per caller; negative: a caller passing a wildcard
        [ 'cleanUnsubscription hash per caller', tk + "        client.resolve ({ 'symbol': symbol }, 'ticker:' + symbol);\n    }\n    unwatch (client: any, symbol: string) {\n        this.unsub (client, 'ticker:' + symbol, 'unsubscribe:ticker:' + symbol);\n    }\n    unsub (client: any, sub: string, unsub: string) {\n        this.cleanUnsubscription (client, sub, unsub);\n    }\n", dictLocal ],
        [ 'negative: cleanUnsubscription under a wildcard caller', tk + "        client.resolve ({ 'symbol': symbol }, 'ticker:' + symbol);\n    }\n    unwatch (client: any, message: Dict) {\n        this.unsub (client, 'x', this.safeString (message, 'h'));\n    }\n    unsub (client: any, sub: string, unsub: string) {\n        this.cleanUnsubscription (client, sub, unsub);\n    }\n", valueLocal ],
    ];
    for (const [ name, handlers, want ] of cases) {
        test(name, () => {
            expect(mk(handlers)).toMatch(want);
        });
    }
});

describe('ral-40a: nil-declared Dict locals lent to extend', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type NullableDict = Dict | undefined;\nexport default class Exchange {\n    omit (o: any, ...keys: any[]): any { return o; }\n    extend (...args: any[]): any { return Object.assign ({}, ...args); }\n    deepExtend (...args: any[]): any { return Object.assign ({}, ...args); }\n    hold (x: any): any { return x; }\n}\n";
    const venue = "import Exchange from './base/Exchange.js';\nimport type { Dict, NullableDict } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    createOrderRequest (params: Dict = {}, tif: boolean = false) {\n        const request: Dict = { 'a': 1 };\n        let requestParams: NullableDict = undefined;\n        if (tif) {\n            requestParams = this.omit (params, [ 'tif' ]);\n        } else {\n            requestParams = this.omit (params, 'x');\n        }\n        return this.extend (request, requestParams);\n    }\n    deepRequest (params: Dict = {}, tif: boolean = false) {\n        const request: Dict = { 'a': 1 };\n        let deepParams = undefined;\n        if (tif) {\n            deepParams = this.omit (params, [ 'tif' ]);\n        }\n        return this.deepExtend (request, deepParams);\n    }\n}\n";
    const out = () => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-40a-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), venue);
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    test('an omit-only nil local whose one use is the extra operand of extend is Option<Dict> lent as &[&x]', () => {
        const text = out();
        const co = text.slice(text.indexOf('fn createOrderRequest'), text.indexOf('fn deepRequest'));
        expect(co).toContain('let mut requestParams: Option<crate::value::Dict> = None');
        expect(co).toContain('.into_opt_dict();');
        expect(co).toContain('&[&requestParams]');
        expect(co).not.toContain('requestParams.clone()');
        // negative: deepExtend merges a list operand too, so its operand keeps the box
        const de = text.slice(text.indexOf('fn deepRequest'));
        expect(de).toContain('let mut deepParams: Value = Value::Null');
    });
});

describe('ral-40a: bool nil locals written through `!` cycles and bool locals', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Bool = boolean | undefined;\nexport default class Exchange {\n    safeString (o: any, k: any, d: any = undefined): string | undefined { return o; }\n}\n";
    const venue = "import Exchange from './base/Exchange.js';\nimport type { Dict, Bool } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    parseKind (row: Dict, kind: string) {\n        let linear: Bool = undefined;\n        let inverse: Bool = undefined;\n        if (kind === 'a') {\n            linear = (kind.indexOf ('_v') >= 0);\n            inverse = !linear;\n        } else {\n            if (kind === 'b') {\n                inverse = true;\n            } else {\n                inverse = false;\n            }\n            linear = !inverse;\n        }\n        return { 'linear': linear, 'inverse': inverse };\n    }\n    parseAny (rows: Dict[], wanted: boolean) {\n        let anyActive = false;\n        for (let i = 0; i < rows.length; i++) {\n            if (this.safeString (rows[i], 's') === 'active') {\n                anyActive = true;\n            }\n        }\n        let active: Bool = undefined;\n        if (wanted) {\n            active = anyActive;\n        }\n        return { 'active': active };\n    }\n    parseMixed (row: Dict, kind: string) {\n        let spot = undefined;\n        let other = undefined;\n        if (kind === 'a') {\n            spot = row['x'];\n            other = !spot;\n        } else {\n            other = true;\n            spot = !other;\n        }\n        return { 'spot': spot, 'other': other };\n    }\n}\n";
    const out = () => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-40a-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), venue);
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    test('a `!x` cycle between two nil locals settles both as Option<bool>', () => {
        const text = out();
        const k = text.slice(text.indexOf('fn parseKind'), text.indexOf('fn parseAny'));
        expect(k).toContain('let mut linear: Option<bool> = None');
        expect(k).toContain('let mut inverse: Option<bool> = None');
        expect(k).toContain('inverse = Some(!(linear == Some(true)));');
        expect(k).toContain('linear = Some(!(inverse == Some(true)));');
        expect(k).not.toContain('.clone()');
    });
    test('a native bool local written into a nil local is `Some(x)` and keeps its own rule', () => {
        const text = out();
        const a = text.slice(text.indexOf('fn parseAny'), text.indexOf('fn parseMixed'));
        expect(a).toContain('let mut anyActive: bool = false');
        expect(a).toContain('let mut active: Option<bool> = None');
        expect(a).toContain('active = Some(anyActive);');
        expect(a).not.toContain('.clone()');
    });
    test('negative: a cycle whose other local has a Value write stays mixed (both boxed)', () => {
        const text = out();
        const m = text.slice(text.indexOf('fn parseMixed'));
        expect(m).toContain('let mut spot: Value = Value::Null');
        expect(m).not.toContain('Option<bool>');
    });
});

