        const out = run ("        const end = this.sum (since, 60000);\n        return this.g ({ 'end': end });\n");
        expect(out).toContain('let mut end: Option<i64> = (if let Some(__m0) = since.as_i64() { Some((__m0 + 60000)) } else { None });');
