describe('ral-44e: ethEncodeStructuredData is a byte producer, its locals hold crate::value::Bytes', () => {
    const base = "export interface Dict { [key: string]: any }\nexport default class Exchange {\n    privateKey: string = '';\n"
        + "    hash (request: any, hash: any, digest: string = 'hex'): any { return ''; }\n"
        + "    ethEncodeStructuredData (domain: any, messageTypes: any, messageData: any): Uint8Array { return new Uint8Array (); }\n}\n";
    const venue = "import Exchange from './base/Exchange.js';\nimport type { Dict } from './base/Exchange.js';\n"
        + "export default class venue extends Exchange {\n"
        + "    signMessage (message: any, privateKey: string): string { return this.hash (message, 'keccak', 'hex'); }\n"
        + "    signIt (domain: Dict, types: Dict, request: Dict): string {\n        const msg = this.ethEncodeStructuredData (domain, types, request);\n        return this.signMessage (msg, this.privateKey);\n    }\n"
        + "    digestIt (domain: Dict, types: Dict, request: Dict): string {\n        const encoded = this.ethEncodeStructuredData (domain, types, request);\n        return '0x' + this.hash (encoded, 'keccak', 'hex');\n    }\n"
        + "    leaked (domain: Dict, types: Dict, request: Dict): number {\n        const raw = this.ethEncodeStructuredData (domain, types, request);\n        return raw.length;\n    }\n}\n";
    const out = () => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-44e-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), venue);
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    test('the encoded local is Bytes, shared into a venue signer and lent to hash', () => {
        const text = out();
        expect(text).toMatch(/let mut msg: crate::value::Bytes = self\.ethEncodeStructuredData\(/);
        expect(text).toMatch(/self\.signMessage\(Value::from\(&msg\)/);
        expect(text).toMatch(/let mut encoded: crate::value::Bytes = self\.ethEncodeStructuredData\(/);
        expect(text).toMatch(/self\.hash\(&encoded, /);
    });
    test('negative: a byte local read outside the byte slots and hand-offs keeps its Value box', () => {
        const text = out();
        expect(text).toMatch(/let mut raw: Value = Value::from\(self\.ethEncodeStructuredData\(/);
    });
});

describe('ral-44c: a params alias held as the map through an omit rewrite', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Int = number | undefined;\nexport type Str = string | undefined;\nexport default class Exchange {\n    extend (...args: any[]): any { return Object.assign ({}, ...args); }\n    omit (x: any, ...args: any[]): any { return x; }\n    hold (x: any): any { return x; }\n    async privateGetX (p: any = {}): Promise<any> { return p; }\n}\n";
    const venue = "import Exchange from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async fetchTrades (symbol: string, since: Int = undefined, limit: Int = undefined, params: Dict = {}): Promise<any[]> {\n        const request: Dict = { 'a': 1 };\n        let paramsOmitted = params;\n        if (request['a'] === 1) {\n            paramsOmitted = this.omit (params, 'network');\n        }\n        return await this.privateGetX (this.extend (request, paramsOmitted));\n    }\n    async fetchOrder (id: string, symbol: string = undefined, params: Dict = {}): Promise<any> {\n        let selfOmit: Dict = params;\n        if (id === '1') {\n            selfOmit = this.omit (selfOmit, 'until');\n        }\n        let merged: Dict = params;\n        if (id === '2') {\n            merged = this.extend (params, { 'marker': 1 });\n        }\n        const first = await this.privateGetX (this.extend ({ 'a': 1 }, selfOmit));\n        return await this.privateGetX (this.extend ({ 'b': first }, merged));\n    }\n    async fetchTicker (symbol: string, params: Dict = {}): Promise<any> {\n        let moved: Dict = params;\n        if (symbol === '1') {\n            moved = this.omit (moved, 'until');\n        }\n        return await this.privateGetX (this.extend ({ 'a': 1 }, moved));\n    }\n    rebound (x: any) {\n        let y = x;\n        y = this.omit (x, 'k');\n        return this.hold (this.extend ({}, y));\n    }\n}\n";
    const out = () => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-44c-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), venue.replace("import Exchange from './base/Exchange.js';\n", "import Exchange from './base/Exchange.js';\nimport type { Dict, Int } from './base/Exchange.js';\n"));
        const t = new Transpiler({ 'verbose': false, 'rust': { 'typedUnified': ['fetchTrades', 'fetchOrder', 'fetchTicker'], 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    test('`let y = params` of a typed unified method is a Dict alias; the omit write takes the map back; a plain any parameter alias keeps the box', () => {
        const text = out();
        const t1 = text.slice(text.indexOf('fn fetchTrades'), text.indexOf('fn rebound'));
        expect(t1).toContain('let mut paramsOmitted: crate::value::Dict = params.clone().into_dict();');
        expect(t1).toMatch(/paramsOmitted = self\.omit\(params, [^\n]*\)\.into_dict\(\);/);
        expect(t1).toContain('&[&paramsOmitted]');
        const t3 = text.slice(text.indexOf('fn fetchOrder'), text.indexOf('fn rebound'));
        expect(t3).toContain('let mut selfOmit: crate::value::Dict = params.clone().into_dict();');
        expect(t3).toMatch(/selfOmit = self\.omit\(&selfOmit, [^\n]*\)\.into_dict\(\);/);
        expect(t3).toContain('let mut merged: crate::value::Dict = params.clone().into_dict();');
        // params not read after the alias: it moves in (no Arc copy, as the boxed alias moved it)
        const t4 = text.slice(text.indexOf('fn fetchTicker'), text.indexOf('fn rebound'));
        expect(t4).toContain('let mut moved: crate::value::Dict = params.into_dict();');
        const t2 = text.slice(text.indexOf('fn rebound'));
        expect(t2).toContain('let mut y: Value =');
    });
});

describe('ral-44c: a let local started from a lent market slot is an owned Option<Market>', () => {
    test('`let m: Market = market` rebound from this.market (..) and handed to a market slot prints Option<Market> with no from_raw', () => {
        const dir = path.join (rustFixtureRoot, 'ral44c-market-slot-alias');
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport interface MarketInterface { symbol: string; [key: string]: any }\nexport type Market = MarketInterface | undefined;\nexport default class Exchange {\n    safeString (o: any, k: any, d: Str = undefined): Str { return o; }\n    market (symbol: string): MarketInterface { return undefined; }\n    // METHODS BELOW THIS LINE ARE TRANSPILED FROM TYPESCRIPT\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Market } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    parseTicker (ticker: Dict, market: Market = undefined): Dict {\n        return { 'symbol': this.safeString (market, 'symbol') };\n    }\n    parseTrade (trade: Dict, market: Market = undefined): Dict {\n        let marketResolved: Market = market;\n        const symbol = this.safeString (trade, 's');\n        if (symbol !== undefined) {\n            marketResolved = this.market (symbol);\n        }\n        const id = this.safeString (marketResolved, 'id');\n        return this.parseTicker ({ 'id': id }, marketResolved);\n    }\n}\n");
        const out = new Transpiler({ 'verbose': false, 'rust': { 'typedUnified': ['market'], 'parser': { 'NUM_LINES_END_FILE': 0 } } }).transpileRustByPath (path.join (dir, 'ts/src/venue.ts')).content;
        const t = out.slice(out.indexOf('fn parseTrade'));
        expect(t).toContain('let mut marketResolved: Option<crate::types::Market> = market.cloned();');
        expect(t).toContain('marketResolved.as_ref()');
        expect(t).not.toContain('from_raw(marketResolved');
    });
});

describe('ral-44d: a `{}` reuse literal rewritten from declared Promise<Dict> endpoints holds the map', () => {
    const run = (body: string) => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-44d-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.mkdirSync(path.join(root, 'ts/src/abstract'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport default class Exchange {\n    hold (x: any): any { return x; }\n    extend (a: any, b: any): Dict { return a; }\n    METHODS_MARKER () {}\n    // METHODS BELOW THIS LINE ARE TRANSPILED FROM TYPESCRIPT\n    parseOrder (order: Dict, market: any = undefined): any { return order; }\n}\n");
        fs.writeFileSync(path.join(root, 'ts/src/abstract/venue.ts'), "import _Exchange from '../base/Exchange.js';\nimport type { Dict } from '../base/Exchange.js';\nexport default abstract class Exchange extends _Exchange {\n    privatePostA (params = {}): Promise<Dict> { return this.hold (params); }\n    privatePostB (params = {}): Promise<Dict> { return this.hold (params); }\n    privatePostC (params = {}): Promise<any> { return this.hold (params); }\n}\n");
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), "import Exchange from './abstract/venue.js';\nimport type { Dict } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    override parseOrder (order: Dict, market: any = undefined): any { return order['id']; }\n" + body + "}\n");
        const out = transpiler.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content;
        fs.rmSync(root, { recursive: true, force: true });
        return out;
    };
    test('every write a declared Promise<Dict> endpoint: Dict local, writes `.await.into_dict()`, lent to parseOrder', () => {
        const out = run("    async m (c: boolean, params: Dict = {}): Promise<any> {\n        let response: Dict = {};\n        if (c) {\n            response = await this.privatePostA (params);\n        } else {\n            response = await this.privatePostB (params);\n        }\n        return this.parseOrder (response);\n    }\n");
        expect(out).toMatch(/let mut response: crate::value::Dict = /);
        expect(out).toMatch(/response = self\.private_post_a\(.*\)\.await\.into_dict\(\);/);
        expect(out).toMatch(/self\.parseOrder\(&response/);
    });
    test('a write from an undeclared (Promise<any>) endpoint keeps the local Value', () => {
        const out = run("    async m (c: boolean, params: Dict = {}): Promise<any> {\n        let response: Dict = {};\n        if (c) {\n            response = await this.privatePostA (params);\n        } else {\n            response = await this.privatePostC (params);\n        }\n        return this.parseOrder (response);\n    }\n");
        expect(out).toMatch(/let mut response: Value = /);
    });
});

