        expect(out).toMatch(/entry = self\.extend\(entry, &\[Value::Map\([\s\S]*?\)\]\)\.into_dict\(\);/);
        expect(out).toContain('result.push(Value::Dict(entry));');
        expect(out).not.toContain('entry.clone()');
