describe('ral-48c prediction outcome accessors', () => {
    test('outcome / safeOutcome / loadOutcome print Option<Market> (ral-50c) and callers lend the record', () => {
        const dir = path.join (rustFixtureRoot, 'typed-outcome-accessors');
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport interface MarketInterface { symbol: string; [key: string]: any }\nexport type Market = MarketInterface | undefined;\nexport default class Exchange {\n    safeValue (o: any, k: any, d: any = undefined): any { return o; }\n    safeString (o: any, k: any, d: Str = undefined): Str { return o; }\n    hold (x: any): any { return x; }\n    // METHODS BELOW THIS LINE ARE TRANSPILED FROM TYPESCRIPT\n    parseTicker (ticker: Dict, market: Market = undefined): Dict {\n        return this.safeValue (market, 'symbol') ? ticker : ticker;\n    }\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/base/PredictionExchange.ts'), "import Exchange from './Exchange.js';\nimport type { Dict, Market, MarketInterface, Str } from './Exchange.js';\nexport interface PredictionOutcomeHandle extends MarketInterface { outcome?: Str; }\nexport interface PredictionOutcomeMarket extends PredictionOutcomeHandle { outcome: string; }\nexport default class PredictionExchange extends Exchange {\n    outcomes: Dict = undefined;\n    outcome (outcomeSymbol: Str): PredictionOutcomeMarket {\n        return this.safeValue (this.outcomes, outcomeSymbol);\n    }\n    safeOutcome (outcomeIdOrSymbol: Str, market: Market = undefined): PredictionOutcomeHandle {\n        if (market !== undefined) {\n            return market;\n        }\n        return this.safeValue (this.outcomes, outcomeIdOrSymbol);\n    }\n    async loadOutcome (outcomeSymbol: Str, reload = false): Promise<PredictionOutcomeHandle> {\n        return this.safeOutcome (outcomeSymbol);\n    }\n    async fetchTicker (outcome: string, params: Dict = {}): Promise<Dict> {\n        await this.loadOutcome (outcome);\n        const outcomeObj = await this.loadOutcome (outcome);\n        const id = this.safeString (outcomeObj, 'outcomeId');\n        const other = this.outcome (outcome) as any;\n        this.hold (outcomeObj as any);\n        return this.parseTicker ({ 'id': id, 'o': this.safeString (other, 'id') }, outcomeObj as any);\n    }\n}\n");
        const typed = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        const out = typed.transpileRustByPath (path.join (dir, 'ts/src/base/PredictionExchange.ts')).content;
        // ral-50c: `outcome` / `safeOutcome` answer the record again (their consumers are typed in the same change)
        expect(out).toMatch(/fn outcome\(&self, (?:mut )?outcomeSymbol: Value\) -> Option<crate::types::Market>/);
        expect(out).toMatch(/market: Option<&crate::types::Market>\) -> Option<crate::types::Market>/);
        expect(out).toMatch(/fn loadOutcome\([^\n]*-> Option<crate::types::Market>/);
        expect(out).not.toContain('FromRaw>::from_raw(self.safeOutcome(outcomeSymbol, None))');
        // a discarded warm-up stays unboxed, the local is the typed record lent to the market slot
        expect(out).toMatch(/\n\s*self\.loadOutcome\(outcome\.clone\(\), &\[\]\)\.await;/);
        expect(out).toContain('let mut outcomeObj: Option<crate::types::Market> = self.loadOutcome(outcome.clone(), &[]).await;');
        expect(out).toContain('let mut other: Option<crate::types::Market>');
        // ral-49c: `x as any` handed whole to a `Value` slot boxes the record's raw (no decode back to Value)
        expect(out).toContain('self.hold(crate::Value::from(outcomeObj.as_ref()))');
        expect(out).toContain('outcomeObj.as_ref())');
        expect(out).not.toContain('FromRaw>::from_raw(outcomeObj');
    });
});

describe('ral-49h: a guarded handler-table read (aster / modetrade / xt ternary) and a handler reference rewrite', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport default class Exchange {\n    safeValue (o: any, k: any, d: any = undefined): any { return o[k]; }\n    safeString (o: any, k: any, d: Str = undefined): Str { return o[k]; }\n    safeDict (o: any, k: any, d: any = undefined): any { return o[k]; }\n}\n";
    const client = "export default class Client {\n    resolve (v: any, h: string | undefined = undefined): void {}\n}\n";
    const pro = "import Exchange from '../base/Exchange';\nimport type { Dict } from '../base/Exchange';\nimport Client from '../base/ws/Client';\nexport default class venue extends Exchange {\n    handleA (client: Client, message: Dict) {}\n    handleB (client: Client, message: Dict) {}\n    handleMessage (client: Client, message: Dict) {\n        const methods: Dict = {\n            'a': this.handleA,\n            'b': this.handleB,\n        };\n        const event = this.safeString (message, 'e');\n        let method = (event === undefined) ? undefined : this.safeValue (methods, event);\n        if (event === 'b') {\n            method = this.handleB;\n        }\n        if (method !== undefined) {\n            method.call (this, client, message);\n        }\n    }\n    handleOther (client: Client, message: Dict) {\n        const table: Dict = {\n            'a': this.handleA,\n        };\n        const key = this.safeString (message, 'k');\n        const other = (key === undefined) ? undefined : this.safeValue (table, key);\n        if (other !== undefined) {\n            other.call (this, client, message);\n        }\n        const keys = Object.keys (table);\n        for (let i = 0; i < keys.length; i++) {\n            const k = keys[i];\n            if (key === k) {\n                const byKey = table[k];\n                byKey.call (this, client, message);\n            }\n        }\n        const loose = (key === undefined) ? undefined : this.safeValue (message, key);\n        if (loose !== undefined) {\n            loose.call (this, client, message);\n        }\n    }\n}\n";
    let out = '';
    beforeAll(() => {
        const dir = path.join (rustFixtureRoot, 'ral49h-ws');
        fs.mkdirSync (path.join (dir, 'ts/src/base/ws'), { recursive: true });
        fs.mkdirSync (path.join (dir, 'ts/src/pro'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync (path.join (dir, 'ts/src/base/ws/Client.ts'), client);
        fs.writeFileSync (path.join (dir, 'ts/src/pro/venue.ts'), pro);
        out = transpiler.transpileRustByPath (path.join (dir, 'ts/src/pro/venue.ts')).content;
    });
    test('the guarded read is Option<String> with a None arm and the reference rewrite keeps it', () => {
        expect(out).toMatch(/let mut method: Option<String> = \(if [^\n]*\{ None \} else \{ self\.safe_?[vV]alue\(&methods[^\n]*\.as_str\(\)\.map\(str::to_owned\) \}\)/);
        expect(out).toMatch(/\n\s*method = [^\n]*\.as_str\(\)\.map\(str::to_owned\);/);
        expect(out).toMatch(/let mut other: Option<String> = \(if /);
        expect(out).toContain('method.is_some()');
    });
    test('a table also read by Object.keys and table[k] stays a handler table: the element read is Option<String>', () => {
        expect(out).toMatch(/let mut other: Option<String> = \(if /);
        expect(out).toMatch(/let mut byKey: Option<String> = [^\n]*\.as_str\(\)\.map\(str::to_owned\);/);
    });
    test('a guarded read of a non-table map stays a Value', () => {
        expect(out).toMatch(/let mut loose: Value = /);
    });
});

describe('ral-49a: a shared-map alias asked while its source is still deciding is decided again once the source settles', () => {
    test('`let paramsOrder: Dict = paramsOmitted` rewritten as an omit of a proven map stays a Dict', () => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-49a-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport type Int = number | undefined;\nexport type Bool = boolean | undefined;\nconst omit = (x: Dict | undefined, ...args: any) => x;\nconst extend = (...args: any[]) => Object.assign ({}, ...args);\nexport default class Exchange {\n    omit = omit;\n    extend = extend;\n    safeString2 (o: any, k: any, k2: any, d: Str = undefined): Str { return o; }\n    safeNumber (o: any, k: any, d: any = undefined): any { return o; }\n    safeBool2 (o: any, k: any, k2: any, d: Bool = undefined): Bool { return o; }\n    async privatePostA (p: any = {}): Promise<any> { return p; }\n    // METHODS BELOW THIS LINE ARE TRANSPILED FROM TYPESCRIPT\n    handleOptionBoolAndParams (params: Dict, methodName: Str, optionName: string, defaultValue: Bool = undefined): [Bool, Dict] {\n        const value = this.safeBool2 (params, optionName, methodName, defaultValue);\n        const paramsOmitted = (value !== undefined) ? this.omit (params, optionName) : params;\n        return [ value, paramsOmitted ];\n    }\n}\n");
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Int, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async createOrder (symbol: string, type: string, side: string, amount: number, price: number = undefined, params: Dict = {}): Promise<any> {\n        const request: Dict = { 'symbol': symbol };\n        const clientOrderId = this.safeString2 (params, 'clientOrderId', 'client-order-id');\n        if (clientOrderId !== undefined) {\n            request['client-order-id'] = clientOrderId;\n        }\n        const paramsOmitted = this.omit (this.extend ({}, params), [ 'clientOrderId', 'client-order-id' ]);\n        let paramsOrder: Dict = paramsOmitted;\n        if (type === 'market') {\n            const [ requiresPrice, paramsRequiresPrice ] = this.handleOptionBoolAndParams (paramsOmitted, 'createOrder', 'createMarketBuyOrderRequiresPrice', true);\n            const cost = this.safeNumber (paramsRequiresPrice, 'cost');\n            paramsOrder = this.omit (paramsRequiresPrice, 'cost');\n            if (requiresPrice && cost !== undefined) {\n                request['amount'] = cost;\n            }\n        }\n        return await this.privatePostA (this.extend (request, paramsOrder));\n    }\n}\n");
        const t = new Transpiler({ 'verbose': false, 'rust': { 'typedUnified': ['createOrder'], 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        let out = '';
        try { out = t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
        expect(out).toContain('let mut paramsOmitted: crate::value::Dict = ');
        expect(out).toContain('let mut paramsOrder: crate::value::Dict = Value::from(&paramsOmitted).into_dict();');
        expect(out).toMatch(/paramsOrder = self\.omit\(&paramsRequiresPrice, [^\n]*\)\.into_dict\(\);/);
        expect(out).not.toContain('paramsOrder.clone()');
    });
});

describe('ral-49e: an element of a map local\'s own Object.keys list keys that map as a borrowed string', () => {
    const base = "export interface Dict { [key: string]: any }\nexport interface Dictionary<T> { [key: string]: T }\nexport default class Exchange {\n    safeDict (o: any, k: any, d: Dict = undefined): Dict | undefined { return o; }\n    hold (x: any): any { return x; }\n}\n";
    const run = (body: string) => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-49e-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Dictionary } from './base/Exchange.js';\nexport default class venue extends Exchange {\n" + body + "}\n");
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    const body = (decl: string) => "    m (response: any) {\n        const ledger" + decl + " = this.safeDict (response, 'ledger', {});\n        const keys = Object.keys (ledger);\n        const items = [];\n        for (let i = 0; i < keys.length; i++) {\n            const key = keys[i];\n            const value = ledger[key];\n            value['id'] = key;\n            items.push (value);\n        }\n        return this.hold (items);\n    }\n";
    test('kraken fetchLedger: the key borrows off the list and reads the Dictionary<Dict> row', () => {
        const out = run(body(': Dictionary<Dict>'));
        expect(out).toContain('let mut key: Option<&str> = keys.get(i as usize).and_then(Value::as_str);');
        expect(out).toContain('get_value(&ledger, key.as_deref())');
    });
    test('guard: an untyped row read (a Value bind ccxt writes back) keeps the Value key', () => {
        const out = run(body(': Dict'));
        expect(out).toContain('fn m');
        expect(out).toMatch(/let mut key: Value = /);
    });
});

