describe('ral-50c prediction outcome consumers', () => {
    test('fetchOutcome (Promise<any> in ts/src) answers the outcome record, a {}-armed outcome ternary and a map store keep the record', () => {
        const dir = path.join (rustFixtureRoot, 'typed-outcome-consumers');
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport interface MarketInterface { symbol: string; [key: string]: any }\nexport type Market = MarketInterface | undefined;\nexport default class Exchange {\n    safeValue (o: any, k: any, d: any = undefined): any { return o; }\n    safeString (o: any, k: any, d: any = undefined): Str { return o; }\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/base/PredictionExchange.ts'), "import Exchange from './Exchange.js';\nimport type { Dict, Market, MarketInterface, Str } from './Exchange.js';\nexport interface PredictionOutcomeHandle extends MarketInterface { outcome?: Str; }\nexport interface PredictionOutcomeMarket extends PredictionOutcomeHandle { outcome: string; }\nexport default class PredictionExchange extends Exchange {\n    outcomes: Dict = undefined;\n    outcome (outcomeSymbol: Str): PredictionOutcomeMarket {\n        return this.safeValue (this.outcomes, outcomeSymbol);\n    }\n    safeOutcome (outcomeIdOrSymbol: Str, market: Market = undefined): PredictionOutcomeHandle {\n        return this.safeValue (this.outcomes, outcomeIdOrSymbol);\n    }\n    async fetchOutcome (outcomeSymbol: string): Promise<any> {\n        return this.safeOutcome (outcomeSymbol);\n    }\n    async loadOutcome (outcomeSymbol: Str, reload = false): Promise<PredictionOutcomeHandle> {\n        return await this.fetchOutcome (outcomeSymbol);\n    }\n    parseT (trade: Dict, market: Market = undefined): Dict {\n        let mkt: Market = undefined;\n        if (market !== undefined) {\n            mkt = market;\n        } else {\n            mkt = this.safeOutcome (this.safeString (trade, 'asset'));\n        }\n        return { 'label': this.safeString (mkt, 'label') };\n    }\n    pos (outcomes: string[]): Dict {\n        const wantedIds: Dict = {};\n        for (let i = 0; i < outcomes.length; i++) {\n            const posObj = this.outcome (outcomes[i]);\n            wantedIds[posObj['outcomeId']] = true;\n        }\n        return wantedIds;\n    }\n    wanted (outcome: Str, targets: string[]): Str {\n        const wantedObj: Dict = (outcome !== undefined) ? this.outcome (outcome) : {};\n        const byId: Dict = {};\n        for (let i = 0; i < targets.length; i++) {\n            const outcomeObj = this.outcome (targets[i]);\n            byId[targets[i]] = outcomeObj;\n        }\n        return this.safeString (wantedObj, 'outcome');\n    }\n}\n");
        const typed = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        const out = typed.transpileRustByPath (path.join (dir, 'ts/src/base/PredictionExchange.ts')).content;
        expect(out).toMatch(/fn fetchOutcome\([^\n]*-> Option<crate::types::Market>/);
        // the record is handed on as is: no decode / box round trip
        expect(out).toContain('return self.safeOutcome(outcomeSymbol, None);');
        expect(out).not.toContain('IntoRaw::into_raw(self.safeOutcome');
        expect(out).not.toContain('IntoRaw::into_raw(self.outcome');
        // the `{}` arm reads as `None` for the key reads it only takes
        expect(out).toContain('let mut wantedObj: Option<crate::types::Market> = (if ');
        expect(out).toContain('{ None })');
        // a whole map store boxes the record's raw
        expect(out).toContain('let mut outcomeObj: Option<crate::types::Market> = self.outcome(');
        expect(out).toContain('crate::Value::from(outcomeObj.as_ref())');
        // a lent market parameter copied into the local, and a key read used as another map's key
        expect(out).toContain('let mut mkt: Option<crate::types::Market> = None');
        expect(out).toContain('mkt = market.cloned()');
        expect(out).toContain('let mut posObj: Option<crate::types::Market> = self.outcome(');
        expect(out).toContain('crate::value::KeyRead::key_read(&&posObj, "outcomeId")');
    });
});

