describe('ral-53a: params aliases of a dict ternary and endpoint hand-offs', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport type Int = number | undefined;\nconst omit = (x: Dict | undefined, ...args: any) => x;\nconst extend = (...args: any[]) => Object.assign ({}, ...args);\nexport default class Exchange {\n    omit = omit;\n    extend = extend;\n    safeInteger (o: any, k: any, d: Int = undefined): Int { return o; }\n    safeInteger2 (o: any, k: any, k2: any, d: Int = undefined): Int { return o; }\n    safeBool (o: any, k: any, d: boolean = undefined): boolean { return o; }\n    handleOptionBoolAndParams (params: object, methodName: string, optionName: string, defaultValue: boolean = undefined): [ boolean, Dict ] { return [ defaultValue, params as Dict ]; }\n    async fetchPaginatedCallDeterministic (m: string, s: Str, since: Int, l: Int, tf: Str, p: Dict, max: Int): Promise<any> { return p; }\n    async privateGetA (p: any = {}): Promise<any> { return p; }\n    async privateGetB (p: any = {}): Promise<any> { return p; }\n    isX (): boolean { return true; }\n    safeString (o: any, k: any, d: Str = undefined): Str { return o; }\n}\n";
    const emit = (venue: string): string => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-53a-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), venue);
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try { return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content; } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    test('a dict ternary with a slot arm stays Dict when it initialises a further alias, and that alias shares its map', () => {
        const out = emit("import Exchange from './base/Exchange.js';\nimport type { Dict, Int, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async fetchFundingRateHistory (symbol: Str = undefined, since: Int = undefined, limit: Int = undefined, params: Dict = {}) {\n        const [ paginate, paramsPaginate ] = this.handleOptionBoolAndParams (params, 'f', 'paginate', false);\n        if (paginate) {\n            return await this.fetchPaginatedCallDeterministic ('f', symbol, since, limit, '8h', paramsPaginate, 720);\n        }\n        const request: Dict = { 'symbol': symbol };\n        const until = this.safeInteger2 (paramsPaginate, 'until', 'end_timestamp');\n        const paramsUntil: Dict = (until !== undefined) ? this.omit (paramsPaginate, [ 'until' ]) : paramsPaginate;\n        const isPaginationCall = this.safeBool (paramsUntil, 'x', false);\n        let paramsOmitted: Dict = paramsUntil;\n        if (isPaginationCall) {\n            paramsOmitted = this.omit (paramsUntil, 'x');\n        }\n        return await this.privateGetA (this.extend (request, paramsOmitted));\n    }\n}\n");
        expect(out).toContain('let mut paramsUntil: crate::value::Dict = (if (until.is_some()) { self.omit(&paramsPaginate, &["until"], &[]).into_dict() } else { paramsPaginate });');
        expect(out).toContain('let mut paramsOmitted: crate::value::Dict = Value::from(&paramsUntil).into_dict();');
        expect(out).toContain('self.extend(Value::Map(request), &[&paramsOmitted])');
    });
    test('guard: a ternary with an undefined arm keeps Value and so does its alias', () => {
        const out = emit("import Exchange from './base/Exchange.js';\nimport type { Dict, Int, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async fetchFundingRateHistory (symbol: Str = undefined, since: Int = undefined, limit: Int = undefined, params: Dict = {}) {\n        const [ paginate, paramsPaginate ] = this.handleOptionBoolAndParams (params, 'f', 'paginate', false);\n        if (paginate) {\n            return await this.fetchPaginatedCallDeterministic ('f', symbol, since, limit, '8h', paramsPaginate, 720);\n        }\n        const request: Dict = { 'symbol': symbol };\n        const until = this.safeInteger2 (paramsPaginate, 'until', 'end_timestamp');\n        const paramsUntil: Dict = (until !== undefined) ? paramsPaginate : undefined;\n        const isPaginationCall = this.safeBool (paramsUntil, 'x', false);\n        let paramsOmitted: Dict = paramsUntil;\n        if (isPaginationCall) {\n            paramsOmitted = this.omit (paramsUntil, 'x');\n        }\n        return await this.privateGetA (this.extend (request, paramsOmitted));\n    }\n}\n");
        expect(out).toContain('let mut paramsUntil: Value = ');
        expect(out).not.toContain('let mut paramsOmitted: crate::value::Dict');
    });
    test('a shared-map alias handed whole to an endpoint argument boxes there and stays Dict', () => {
        const out = emit("import Exchange from './base/Exchange.js';\nimport type { Dict, Int, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    handleRouteAndParams (methodName: string, params: Dict = {}): Dict {\n        return this.omit (params, 'route');\n    }\n    async fetchBalance (params: Dict = {}) {\n        const paramsResolved = this.handleRouteAndParams ('fetchBalance', params);\n        const code = this.safeString (paramsResolved, 'code');\n        let paramsOmitted: Dict = paramsResolved;\n        if (this.isX ()) {\n            paramsOmitted = this.omit (paramsResolved, 'code');\n        }\n        let response = undefined;\n        if (code !== undefined) {\n            const request: Dict = { 'currency': code };\n            response = await this.privateGetA (this.extend (request, paramsOmitted));\n        } else {\n            response = await this.privateGetB (paramsOmitted);\n        }\n        return response;\n    }\n}\n\n");
        expect(out).toContain('let mut paramsOmitted: crate::value::Dict = Value::from(&paramsResolved).into_dict();');
        expect(out).toContain('self.privateGetB(Value::Dict(paramsOmitted))');
    });
    test('guard: the endpoint hand-off inside a loop keeps the Value alias', () => {
        const out = emit("import Exchange from './base/Exchange.js';\nimport type { Dict, Int, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    handleRouteAndParams (methodName: string, params: Dict = {}): Dict {\n        return this.omit (params, 'route');\n    }\n    async fetchBalance (params: Dict = {}) {\n        const paramsResolved = this.handleRouteAndParams ('fetchBalance', params);\n        const code = this.safeString (paramsResolved, 'code');\n        let paramsOmitted: Dict = paramsResolved;\n        if (this.isX ()) {\n            paramsOmitted = this.omit (paramsResolved, 'code');\n        }\n        let response = undefined;\n        if (code !== undefined) {\n            const request: Dict = { 'currency': code };\n            response = await this.privateGetA (this.extend (request, paramsOmitted));\n        } else {\n            for (let i = 0; i < 2; i++) {\n                response = await this.privateGetB (paramsOmitted);\n            }\n        }\n        return response;\n    }\n}\n\n");
        expect(out).toContain('let mut paramsOmitted: Value = ');
    });
});
describe('ral-53s: an i64 local handed to a base `sum` written whole to another local keeps its type', () => {
    // binance fetchMyTrades: `oneWeek` has a same-named sibling, so the per-binding walk vetted the write `endTime = this.sum (..)`
    const write = (name: string, sum: string) => {
        const dir = path.join (rustFixtureRoot, name);
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export type Int = number | undefined;\nexport default class Exchange {\n    sum (...args: any[]): any { return args[0] + args[1]; }\n    milliseconds (): number { return 0; }\n    safeInteger (o: any, k: any, d: any = undefined): Int { return o[k] ?? d; }\n    hold (x: any): any { return x; }\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Int } from './base/Exchange.js';\nexport default class venue extends Exchange {\n    async f (symbol: string, since: Int = undefined, params = {}): Promise<any> {\n        const request: any = {};\n        let endTime = this.safeInteger (params, 'until');\n        if (since !== undefined) {\n            const startTime = since;\n            request['startTime'] = startTime;\n            const currentTimestamp = this.milliseconds ();\n            const oneWeek = 604800000;\n            if ((currentTimestamp - since) >= oneWeek) {\n                if (endTime === undefined) {\n                    endTime = " + sum + ";\n                    const endTimeValue = (endTime === undefined) ? 0 : endTime;\n                    endTime = Math.min (endTimeValue, currentTimestamp);\n                }\n            }\n        }\n        if (endTime !== undefined) {\n            request['endTime'] = endTime;\n        }\n        if (symbol === 'x') {\n            const endTimeResolved = this.safeInteger (request, 'endTime', this.milliseconds ());\n            if (since === undefined) {\n                const oneWeek = 604800000;\n                request['startTime'] = endTimeResolved - oneWeek;\n            }\n        }\n        return this.hold (request);\n    }\n}\n");
        return transpiler.transpileRustByPath (path.join (dir, 'ts/src/venue.ts')).content;
    };
    test('`endTime = this.sum (startTime, oneWeek)`: oneWeek is an i64 and the sum prints natively', () => {
        const out = write ('53s-sum', 'this.sum (startTime, oneWeek)');
        expect(out).toContain('let mut oneWeek: i64 = 604800000;\n            if ');
        expect(out).toContain('endTime = (if let Some(__m0) = startTime { Some((__m0 + oneWeek)) } else { None });');
        expect(out).not.toContain('self.sum(');
    });
    test('negative: a sum whose other operand is an untyped Value keeps the operand boxed', () => {
        const out = write ('53s-sumn', 'this.sum (params, oneWeek)');
        expect(out).toContain('let mut oneWeek: Value = Value::Int(604800000);');
    });
});

