describe('ral-63e: a split-element key of a pure read chain on an annotated dict (`m[k][j]`, `j in m[k]`) is an Option<String> local', () => {
    const src = (recvType: string, tail: string) => "export type Str = string | undefined;\nexport interface Dict { [key: string]: any }\nclass T {\n    safeString (o: any, k: any, d: Str = undefined): Str { return undefined; }\n    safeDict (o: any, k: any, d: any = undefined): Dict | undefined { return undefined; }\n    fv (paramName: string, x: any): any {\n        const methodDict" + recvType + " = x;\n        const splited = paramName.split ('.');\n        const parentKey = splited[0];\n        const subKey = this.safeString (splited, 1);\n        if (!(parentKey in methodDict)) { return 2; }\n        if (this.safeDict (methodDict, parentKey) === undefined) {\n            return methodDict[parentKey];\n        }\n" + tail + "    }\n}\n";
    const both = "        if (!(subKey in methodDict[parentKey])) { return 3; }\n        return methodDict[parentKey][subKey];\n";
    test('positive: the chain links print the native okey read with the typed key', () => {
        const out = transpiler.transpileRust(src(': Dict', both)).content;
        expect(out).toContain('let mut parentKey: Option<String> = splited.get(0).and_then(Value::as_str).map(str::to_owned);');
        expect(out).toContain('in_op(&(if let (Some(__m), Some(__k)) = (methodDict.as_map(), parentKey.as_deref()) { __m.get(__k).cloned().unwrap_or(Value::Null) } else { Value::Null }), &subKey)');
        expect(out).toContain('return get_value(&(if let (Some(__m), Some(__k)) = (methodDict.as_map(), parentKey.as_deref()) { __m.get(__k).cloned().unwrap_or(Value::Null) } else { Value::Null }), &subKey);');
        expect(out).not.toContain('parentKey.as_str()');
    });
    test('guard: an unannotated receiver keeps the key a Value', () => {
        const out = transpiler.transpileRust(src('', both)).content;
        expect(out).toContain('let mut parentKey: Value = ');
    });
    test('guard: a chain that is written (`m[k][j] = v`) keeps the key a Value', () => {
        const out = transpiler.transpileRust(src(': Dict', "        methodDict[parentKey][subKey] = 1;\n        return 1;\n")).content;
        expect(out).toContain('let mut parentKey: Value = ');
    });
});

describe('ral-63n: an optional safeDict stored whole through a type assertion `m[k] = x as T` (backpack fetchTickers)', () => {
    const base = "export interface Dict { [key: string]: any }\nexport interface Ticker { symbol: string | undefined; }\nexport type Tickers = Dict;\nexport default class Exchange {\n    safeDict (o: any, k: any, d: any = undefined): Dict { return o; }\n}\n";
    const run = (body: string) => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-63n-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Ticker, Tickers } from './base/Exchange.js';\nexport default class venue extends Exchange {\n" + body + "}\n");
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try {
            t.transpileRustByPath(path.join(root, 'ts/src/base/Exchange.ts'));
            return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content;
        } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    // Truth table. `as Ticker` prints nothing: the store takes the local's own value. The held value is Dict or Null (no default);
    // the store boxes it back with map_or(Value::Null, Value::Dict): Null -> Null, {} -> Dict({}), {'a': 1} -> Dict({'a': 1}), the very
    // Value the boxed local inserted; the null test is_some() equals `!= Null`. Nothing is compared as a number.
    const rebox = (h: Record<string, any> | null) => h === null ? null : h;
    test('truth table: the reboxed store equals the boxed one', () => {
        for (const h of [ null, {}, { 'a': 1 } ]) { expect(rebox(h)).toEqual(h); expect(h !== null).toBe(rebox(h) !== null); }
    });
    const backpack = "    fetchTickers (tickers: any, syms: string[], source: string): Tickers {\n        const result: Tickers = {};\n        for (let i = 0; i < syms.length; i++) {\n            const marketSymbol = syms[i];\n            const ticker = this.safeDict (tickers, marketSymbol);\n            if ((ticker !== undefined) && (source !== 'External')) {\n                result[marketSymbol] = ticker as Ticker;\n            }\n        }\n        return result;\n    }\n";
    test('backpack fetchTickers: ticker is Option<Dict> and the asserted store moves it', () => {
        const out = run(backpack);
        expect(out).toContain('let mut ticker: Option<crate::value::Dict> = ');
        expect(out).toContain('ticker.map_or(Value::Null, Value::Dict));');
    });
    test('guard: an asserted value inside a larger expression is not a whole store', () => {
        const out = run(backpack.replace('result[marketSymbol] = ticker as Ticker;', 'result[marketSymbol] = [ ticker as Ticker ];'));
        expect(out).not.toContain('let mut ticker: Option<crate::value::Dict> = ');
    });
});

describe('ral-63n: a no-default safeInteger local ordered against a number-typed Value (base buildOHLCVC / filterBySinceLimit shapes)', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Int = number | undefined;\nexport default class Exchange {\n    safeInteger (o: any, k: any, d: Int = undefined): Int { return o; }\n    safeDict (o: any, k: any, d: any = undefined): Dict { return o; }\n}\n";
    const run = (body: string) => {
        const root = fs.mkdtempSync(path.join(os.tmpdir(), 'astfx-63n-'));
        fs.mkdirSync(path.join(root, 'ts/src/base'), { recursive: true });
        fs.writeFileSync(path.join(root, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync(path.join(root, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict } from './base/Exchange.js';\nexport default class venue extends Exchange {\n" + body + "}\n");
        const t = new Transpiler({ 'verbose': false, 'rust': { 'parser': { 'NUM_LINES_END_FILE': 0 } } });
        try {
            t.transpileRustByPath(path.join(root, 'ts/src/base/Exchange.ts'));
            return t.transpileRustByPath(path.join(root, 'ts/src/venue.ts')).content;
        } finally { fs.rmSync(root, { recursive: true, force: true }); }
    };
    // Truth table of the new compare form `matches!(x, Some(__p) if (__p as f64) OP v.as_f64().unwrap_or(f64::NAN))` against the
    // old `x.as_f64().unwrap_or(f64::NAN) OP v.as_f64().unwrap_or(f64::NAN)`. x is a no-default safeInteger: Int or Null (never Float,
    // never Str). The other side v is a number-typed Value: Null, Int, Float, or (unchecked at runtime) Str.
    //   Null on x: old NaN OP _ = false; new None = false.  Null on v: both NaN on the right = false (Some(p) and NaN is false).
    //   Int x vs Int / Float v: both compare (p as f64) with v's f64 payload: same answer (5 < 5.5 true, 5 < 5 false, 6 < 5.5 false).
    //   Int x vs Str v: Value::as_f64 of a Str is None on both forms (NaN), so false on both: no string-to-number coercion either way.
    type V = { t: 'Null' } | { t: 'Int', v: number } | { t: 'Float', v: number } | { t: 'Str', v: string };
    const asF64 = (x: V) => x.t === 'Int' || x.t === 'Float' ? x.v : NaN;
    const ops: Record<string, (a: number, b: number) => boolean> = { '<': (a, b) => a < b, '<=': (a, b) => a <= b, '>': (a, b) => a > b, '>=': (a, b) => a >= b };
    const oldForm = (x: V, v: V, op: string) => ops[op](asF64(x), asF64(v));
    const newForm = (x: V, v: V, op: string) => x.t === 'Int' ? ops[op](x.v, asF64(v)) : false;
    test('truth table: Null on either side, Int against Int / Float, Int against Str agree on every operator', () => {
        const xs: V[] = [ { t: 'Null' }, { t: 'Int', v: 5 }, { t: 'Int', v: 6 }, { t: 'Int', v: -1 } ];
        const vs: V[] = [ { t: 'Null' }, { t: 'Int', v: 5 }, { t: 'Float', v: 5.5 }, { t: 'Float', v: 5.0 }, { t: 'Str', v: '5' } ];
        for (const op of Object.keys(ops)) for (const x of xs) for (const v of vs) expect(newForm(x, v, op)).toBe(oldForm(x, v, op));
    });
    const shape = "    build (trades: any[], since: number = 0, ms: number = 1): any {\n        for (let i = 0; i < trades.length; i++) {\n            const trade = this.safeDict (trades, i, {});\n            const ts = this.safeInteger (trade, 'timestamp');\n            if (ts === undefined) {\n                continue;\n            }\n            if (ts < since) {\n                continue;\n            }\n            return Math.floor (ts / ms) * ms;\n        }\n        return undefined;\n    }\n";
    test('buildOHLCVC ts: Option<i64>, the ordered test prints the matches! form and the arithmetic boxes it back', () => {
        const out = run(shape);
        expect(out).toContain('let mut ts: Option<i64> = ');
        expect(out).toContain('matches!(ts, Some(__p) if (__p as f64) < since.as_f64().unwrap_or(f64::NAN))');
        expect(out).toContain('(Value::from(ts)).as_f64()');
    });
    test('guard: a reader with a default keeps its own decision (the default may be any number)', () => {
        const out = run(shape.replace("this.safeInteger (trade, 'timestamp')", "this.safeInteger (trade, 'timestamp', ms)"));
        expect(out).not.toContain('matches!(ts, Some(__p) if (__p as f64) < since');
    });
    test('guard: an any-typed partner is not a number Value and keeps the box', () => {
        const out = run(shape.replace('since: number = 0', 'since: any = 0'));
        expect(out).not.toContain('let mut ts: Option<i64> = ');
    });
});

describe('ral-63p: an i64 base sum bounding a counter loop that starts at an i64 local', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type Int = number | undefined;\nconst sum = (...args) => {\n    const result = args.filter ((x) => x !== undefined);\n    return (result.length > 0) ? result.reduce ((a, b) => a + b, 0) : undefined;\n};\nexport default class Exchange {\n    options: Dict = {};\n    sum = sum;\n    safeInteger (o: any, k: any, d: Int = undefined): Int { return d; }\n    keep (o: any): any { return o; }\n}\n";
    const write = (name: string, body: string) => {
        const dir = path.join (rustFixtureRoot, name);
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict } from './base/Exchange.js';\nexport default class venue extends Exchange {\n" + body + "}\n");
        return path.join (dir, 'ts/src/venue.ts');
    };
    const loop = (cmp: string) => "    m (tokenIds: string[]) {\n        const n = tokenIds.length;\n        const chunkSize = this.safeInteger (this.options, 'batch', 50);\n        let startIndex = 0;\n        while (startIndex < n) {\n            let endIndex = this.sum (startIndex, chunkSize);\n            if (endIndex > n) {\n                endIndex = n;\n            }\n            const chunk = [];\n            for (let i = startIndex; " + cmp + "; i++) {\n                chunk.push (tokenIds[i]);\n            }\n            this.keep (chunk);\n            startIndex = endIndex;\n        }\n    }\n";
    test('polymarket fetchOutcomes / fetchTickers `endIndex` (and the length it is clamped to) are i64', () => {
        const out = transpiler.transpileRustByPath (write ('ral-63p-sum-bound', loop ('i < endIndex'))).content;
        expect(out).toContain('let mut endIndex: i64 = (startIndex + chunkSize);');
        expect(out).toContain('let mut n: i64 = ');
        expect(out).toContain('i < endIndex }');
    });
    test('negative: the counter written in the body keeps the bound a Value', () => {
        const out = transpiler.transpileRustByPath (write ('ral-63p-sum-bound-w', loop ('i < endIndex').replace ('chunk.push (tokenIds[i]);', 'chunk.push (tokenIds[i]);\n                i = i + 1;'))).content;
        expect(out).toContain('let mut endIndex: Value = ');
    });
});

describe('ral-62o: an Option<String> reader local prints the `_opt` twin of the reader from the call node', () => {
    const build = () => {
        const dir = path.join (rustFixtureRoot, 'ral62o-opt');
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport default class Exchange {\n    options: Dict = {};\n"
            + "    safeString (o: any, k: any, d: Str = undefined): Str { return o[k]; }\n"
            + "    safeString2 (o: any, a: any, b: any, d: Str = undefined): Str { return o[a]; }\n"
            + "    safeStringN (o: any, ks: any[], d: Str = undefined): Str { return o[ks[0]]; }\n"
            + "    safeStringLower (o: any, k: any, d: Str = undefined): Str { return o[k]; }\n"
            + "    safeStringLower2 (o: any, a: any, b: any, d: Str = undefined): Str { return o[a]; }\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n"
            + "    pick (o: Dict, i: number, k: string): string {\n"
            + "        const a = this.safeString (o, 'id');\n"
            + "        const b = this.safeString (o, i);\n"
            + "        const c = this.safeString2 (o, 'x', 'y');\n"
            + "        const d = this.safeStringN (o, [ 'x', 'y' ]);\n"
            + "        const e = this.safeStringLower (o, 'side');\n"
            + "        const f = this.safeStringLower2 (o, 'x', 'y');\n"
            + "        let g = this.safeString (o, 'g');\n"
            + "        if (g === undefined) {\n"
            + "            g = this.safeString (o, 'h');\n"
            + "        }\n"
            + "        if (a === undefined || b === undefined || c === undefined || d === undefined || e === 'buy' || f === 'sell' || g === undefined) {\n"
            + "            return 'none';\n"
            + "        }\n"
            + "        return k;\n"
            + "    }\n}\n");
        return transpiler.transpileRustByPath (path.join (dir, 'ts/src/venue.ts')).content;
    };
    test('literal key: the `_k_opt` twin; Value key / safeString2 / safeStringN: their `_opt` twin; no `.as_str().map(str::to_owned)` tail', () => {
        const out = build ();
        expect(out).toContain('let mut a: Option<String> = self.safe_string_k_opt(o.clone(), "id", &[]);');
        expect(out).toMatch(/let mut b: Option<String> = self\.safe_string_opt\(o\.clone\(\), [^;]*i[^;]*, &\[\]\);/);
        expect(out).toContain('let mut c: Option<String> = self.safe_string2_opt(o.clone(), Value::Str("x".into()), Value::Str("y".into()), &[]);');
        expect(out).toMatch(/let mut d: Option<String> = self\.safe_string_n_opt\(o\.clone\(\), [^;]*, &\[\]\);/);
        expect(out).toContain('let mut e: Option<String> = self.safe_string_lower_k_opt(o.clone(), "side", &[]);');
        expect(out).toMatch(/g = self\.safe_string_k_opt\(o(?:\.clone\(\))?, "h", &\[\]\);/);
        expect(out).not.toMatch(/self\.safe_string(?:_k|_lower_k|2|_n)?\([^;]*\)\.as_str\(\)\.map\(str::to_owned\)/);
    });
    test('a method declared to return a string returns the twin of the reader it hands back', () => {
        const dir = path.join (rustFixtureRoot, 'ral62o-ret');
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport default class Exchange {\n    options: Dict = {};\n"
            + "    safeString (o: any, k: any, d: Str = undefined): Str { return o[k]; }\n}\n");
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n"
            + "    parseStatus (status: Str): Str {\n        const statuses: Dict = { 'a': 'open' };\n        return this.safeString (statuses, status, status);\n    }\n"
            + "    token (): Str {\n        return this.safeString (this.options, 'token');\n    }\n"
            + "    use (s: Str): string {\n        return this.parseStatus (s) + this.token ();\n    }\n}\n");
        const out = transpiler.transpileRustByPath (path.join (dir, 'ts/src/venue.ts')).content;
        expect(out).toMatch(/return self\.safe_string_opt\(&?statuses[^;]*\);/);
        expect(out).toMatch(/return self\.safe_string_k_opt\([^;]*"token", &\[\]\);/);
        expect(out).not.toMatch(/return self\.safe_string[a-z0-9_]*\([^;]*\)\.as_str\(\)\.map\(str::to_owned\);/);
    });
    test('ral-65o: safeStringLower2 now has its `_opt` twin (was the no-twin guard)', () => {
        expect(build ()).toContain('let mut f: Option<String> = self.safe_string_lower2_opt(o.clone(), Value::Str("x".into()), Value::Str("y".into()), &[]);');
    });
});

