describe('ral-67c: declared-empty NullableDict sign headers', () => {
    const base = "export interface Dict { [key: string]: any }\nexport type NullableDict = Dict | undefined;\nexport type Str = string | undefined;\nexport default class Exchange {\n    apiKey: string = '';\n    extend (...args: any[]): Dict { return {}; }\n    keep (x: any): any { return x; }\n}\n";
    const write = (name: string, body: string) => {
        const dir = path.join (rustFixtureRoot, name);
        fs.mkdirSync (path.join (dir, 'ts/src/base'), { recursive: true });
        fs.writeFileSync (path.join (dir, 'ts/src/base/Exchange.ts'), base);
        fs.writeFileSync (path.join (dir, 'ts/src/venue.ts'), "import Exchange from './base/Exchange.js';\nimport type { Dict, NullableDict, Str } from './base/Exchange.js';\nexport default class venue extends Exchange {\n" + body + "}\n");
        transpiler.transpileRustByPath (path.join (dir, 'ts/src/base/Exchange.ts'));
        return transpiler.transpileRustByPath (path.join (dir, 'ts/src/venue.ts')).content;
    };
    const sign = (inner: string) => "    sign (path: string, api = 'public', method = 'GET', params = {}, headers: any = undefined, body: any = undefined) {\n        let url = path;\n        let requestHeaders: NullableDict = undefined;\n        if (api === 'private') {\n" + inner + "        }\n        const headersResult = requestHeaders;\n        return { 'url': url, 'method': method, 'body': body, 'headers': headersResult };\n    }\n";
    test('a map literal then `x = this.extend (x, y)` holds Option<Dict>: the head is taken out and the result put back', () => {
        const out = write ('ral-67c-extend', sign ("            requestHeaders = { 'K': this.apiKey };\n            if (method === 'POST') {\n                requestHeaders = this.extend (requestHeaders, { 'Content-Type': 'application/json' });\n            }\n"));
        expect(out).toContain('let mut requestHeaders: Option<crate::value::Dict> = None;');
        expect(out).toContain('requestHeaders = Some(crate::value::Dict::new({');
        expect(out).toContain('requestHeaders = Some(self.extend(requestHeaders.take(), &[Value::Map({');
        expect(out).toContain('})]).into_dict());');
        expect(out).toContain('let mut headersResult: Option<crate::value::Dict> = requestHeaders;');
        expect(out).toContain('headersResult.map_or(Value::Null, Value::Dict)');
    });
    test('`x = y` of a const map-literal local that stays Value: taken back with into_opt_dict', () => {
        const out = write ('ral-67c-alias', sign ("            const signed: Dict = { 'K': this.apiKey };\n            signed['S'] = url;\n            requestHeaders = signed;\n"));
        expect(out).toContain('let mut requestHeaders: Option<crate::value::Dict> = None;');
        // ral-73a: the literal is now a native map moved into the optional handle (was `signed.into_opt_dict()` on a Value box)
        expect(out).toMatch(/requestHeaders = Some\(crate::value::Dict::new\(signed\)\);/);
    });
    test('negative: an undeclared (`any`) empty local, an extend reading another source, or a non-literal source keeps Value', () => {
        const untyped = write ('ral-67c-neg1', sign ("            requestHeaders = { 'K': this.apiKey };\n").replace('let requestHeaders: NullableDict = undefined;', 'let requestHeaders = undefined;').replace("            requestHeaders = { 'K': this.apiKey };\n", "            requestHeaders = { 'K': this.apiKey };\n            requestHeaders = this.extend (requestHeaders, { 'A': 1 });\n"));
        expect(untyped).toContain('let mut requestHeaders: Value = Value::Null;');
        const other = write ('ral-67c-neg2', sign ("            requestHeaders = { 'K': this.apiKey };\n            requestHeaders = this.extend (params, { 'A': 1 });\n"));
        expect(other).toContain('let mut requestHeaders: Value = Value::Null;');
        const nonLiteral = write ('ral-67c-neg3', sign ("            const signed: Dict = this.keep (params);\n            requestHeaders = signed;\n"));
        expect(nonLiteral).toContain('let mut requestHeaders: Value = Value::Null;');
    });
});

describe('ral-67a: a declared-empty string local read only as Precise operands is Option<String>, lent as `&x`', () => {
    const cls = (decl: string) => `type Str = string | undefined;
class Precise {
    static stringAdd(a: Str, b: Str) { if (a === undefined || b === undefined) { return undefined; } return a + b; }
    static stringMul(a: Str, b: Str) { if (a === undefined || b === undefined) { return undefined; } return a + b; }
}
class A {
    safeString(o: any, k: any, d: Str = undefined): Str { return undefined as any; }
    parseNumber(x: any): any { return x; }
    hold(x: any): any { return x; }
    run(position: any, long: boolean) {
        const rate = this.safeString(position, 'r');
        const size = this.safeString(position, 's');
        ${decl}
        if (long) {
            onePlus = Precise.stringAdd('1', rate);
        } else {
            onePlus = Precise.stringAdd('-1', rate);
        }
        const left = Precise.stringMul(size, onePlus);
        const right = Precise.stringMul(rate, onePlus);
        return this.hold([ this.parseNumber(left), this.parseNumber(right) ]);
    }
}`;
    test('aster / binance parseAccountPosition `onePlusMaintenanceMarginPercentageString`: typed, written from the Precise result, lent at both operands', () => {
        const out = transpiler.transpileRust(cls('let onePlus: Str = undefined;')).content;
        expect(out).toContain('let mut onePlus: Option<String> = None;');
        expect(out).toMatch(/onePlus = crate::precise::Precise::stringAdd\([^;]*\)\.as_str\(\)\.map\(str::to_owned\);/);
        expect(out).toContain('crate::precise::Precise::stringMul(&size, &onePlus)');
        expect(out).toContain('crate::precise::Precise::stringMul(&rate, &onePlus)');
        expect(out).not.toContain('onePlus: Value');
    });
    test('negative: an `any`-declared empty local keeps its Value box', () => {
        const out = transpiler.transpileRust(cls('let onePlus: any = undefined;')).content;
        expect(out).toContain('let mut onePlus: Value = Value::Null;');
    });
});

describe('ral-67e: same-named sibling-block declarations are typed by their own scope', () => {
    test('htx parseCancelOrders shape: a string element whose sibling-loop twin is a Dict boxes at both literal values', () => {
        const root = fs.mkdtempSync (path.join (os.tmpdir (), 'astfx-67e-'));
        try {
            const base = "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport default class Exchange {\n    safeString (o: any, k: any, d: Str = undefined): Str { return o; }\n    safeDict (o: any, k: any, d: Dict = undefined): Dict { return o; }\n    safeList (o: any, k: any, d: any[] = undefined): any[] { return o; }\n    hold (x: any): any { return x; }\n}\n";
            const venue = [
                "import Exchange from './base/Exchange.js';",
                "import type { Dict } from './base/Exchange.js';",
                'export type Strings = string[] | undefined;',
                'export default class venue extends Exchange {',
                '    parseCancels (orders: Dict) {',
                "        const success: Strings = this.safeList (orders, 'success', []);",
                "        const data: Dict[] = this.safeList (orders, 'data', []);",
                '        const result = [];',
                '        for (let i = 0; i < data.length; i++) {',
                '            const order = data[i];',
                "            result.push (this.hold ({ 'info': order }));",
                '        }',
                '        for (let i = 0; i < success.length; i++) {',
                '            const order = success[i];',
                "            result.push (this.hold ({ 'info': order, 'id': order }));",
                '        }',
                '        return result;',
                '    }',
                '}',
                '',
            ].join('\n');
            fs.mkdirSync (path.join (root, 'cancels', 'ts/src/base'), { recursive: true });
            fs.writeFileSync (path.join (root, 'cancels', 'ts/src/base/Exchange.ts'), base);
            fs.writeFileSync (path.join (root, 'cancels', 'ts/src/venue.ts'), venue);
            const out = transpiler.transpileRustByPath (path.join (root, 'cancels', 'ts/src/venue.ts')).content;
            expect(out).toContain('let mut order: Option<String> = success.get(i as usize).and_then(Value::as_str).map(str::to_owned);');
            expect(out).toContain('m.insert("info".to_string(), Value::from(order.as_deref()));');
            expect(out).toContain('m.insert("id".to_string(), Value::from(order.as_deref()));');
            // the sibling twin keeps its own (Dict) decision
            expect(out).toContain('let mut order: Option<crate::value::Dict> = data.get(i as usize)');
        } finally {
            fs.rmSync (root, { recursive: true, force: true });
        }
    });
    const fx = (dir: string) => {
        const root = fs.mkdtempSync (path.join (os.tmpdir (), 'astfx-67e-'));
        const files: Record<string, string> = {
            'ts/src/base/Exchange.ts': "export interface Dict { [key: string]: any }\nexport type Str = string | undefined;\nexport default class Exchange {\n    safeString (o: any, k: any, d: Str = undefined): Str { return o; }\n    safeDict (o: any, k: any, d: Dict = undefined): Dict | undefined { return o; }\n    safeList (o: any, k: any, d: any[] = undefined): any[] | undefined { return o; }\n    hold (x: any): any { return x; }\n}\n",
            'ts/src/venue.ts': [
                "import Exchange from './base/Exchange.js';",
                "import type { Dict, Str } from './base/Exchange.js';",
                'export default class venue extends Exchange {',
                '    parseB (response: Dict, flag: boolean) {',
                "        const a = this.safeString (response, 'a');",
                "        const b = this.safeString (response, 'b');",
                '        if (flag) {',
                '            const total = (a !== undefined) ? a : b;',
                '            const free = (b !== undefined) ? b : total;',
                "            return { 'free': free, 'total': total };",
                '        }',
                "        const rows = this.safeList (response, 'rows', []);",
                '        const result: Dict = {};',
                '        for (let i = 0; i < rows.length; i++) {',
                "            const total = this.hold (rows[i]);",
                "            result['t'] = total;",
                '        }',
                '        return result;',
                '    }',
                '}',
                '',
            ].join('\n'),
        };
        for (const [rel, text] of Object.entries (files)) {
            const out = path.join (root, dir, rel);
            fs.mkdirSync (path.dirname (out), { recursive: true });
            fs.writeFileSync (out, text);
        }
        return root;
    };
    test('a string ternary local whose sibling twin is a Value boxes at its literal-value hand-off', () => {
        const root = fx ('sib');
        try {
            const out = transpiler.transpileRustByPath (path.join (root, 'sib', 'ts/src/venue.ts')).content;
            expect(out).toMatch(/let mut total: Option<String> = \(if \(a\.is_some\(\)\) \{ a\.clone\(\) \} else \{ b\.clone\(\) \}\);/);
            expect(out).toMatch(/let mut free: Option<String> = \(if \(b\.is_some\(\)\) \{ b\.clone\(\) \} else \{ total\.clone\(\) \}\);/);
            expect(out).not.toMatch(/let mut free: Value/);
            // the sibling twin stays the Value it is
            expect(out).toMatch(/let mut total: Value = self\.hold\(/);
        } finally {
            fs.rmSync (root, { recursive: true, force: true });
        }
    });
});

